#include <stdio.h>
int K=15;
int improper(long*c,long N2){ long N=N2/2; for(long T=1;T<=N;T+=2){int cov=0; for(int i=0;i<K;i++){long y=(T*c[i])%N2; long d=y<N2-y?y:N2-y; if(16*d<N2){cov=1;break;}} if(!cov) return 0;} return 1;}
int main(){
 long L[8][15]={{142,96,144,381,523,8,56,104,152,576,436,296,344,584,632},{142,96,144,5,147,8,56,104,152,576,436,296,344,584,632},{330,96,144,287,617,8,56,104,152,576,60,296,344,584,632},{330,96,144,663,241,8,56,104,152,576,60,296,344,584,632},{518,96,144,193,711,8,56,104,152,576,436,296,344,584,632},{518,96,144,569,335,8,56,104,152,576,436,296,344,584,632},{706,96,144,475,429,8,56,104,152,576,60,296,344,584,632},{706,96,144,99,53,8,56,104,152,576,60,296,344,584,632}};
 for(int r=0;r<8;r++){ int odd=0; for(int i=0;i<K;i++) odd+=L[r][i]&1; long c[15],m=0;
  for(int b=0;b<(1<<K);b++){for(int i=0;i<K;i++) c[i]=L[r][i]+(((b>>i)&1)?752:0); m+=improper(c,1504);}
  printf("lift %d: improper at 16p=%d odd=%d improper children at 32p=%ld\n",r+1,improper(L[r],752),odd,m);}
}
